import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGPl1zp.js";const n="/newx-doc/assets/Gemini-%E5%AE%98%E6%96%B9.DOVKgu-U.png",c=JSON.parse('{"title":"【模型接入】谷歌 Gemini","description":"","frontmatter":{},"headers":[],"relativePath":"ai/gemini.md","filePath":"ai/gemini.md","lastUpdated":null}'),s={name:"ai/gemini.md"};function l(o,a,p,h,d,g){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="【模型接入】谷歌-gemini" tabindex="-1">【模型接入】谷歌 Gemini <a class="header-anchor" href="#【模型接入】谷歌-gemini" aria-label="Permalink to &quot;【模型接入】谷歌 Gemini&quot;">​</a></h1><p>项目基于 Spring AI 提供的 <a href="https://docs.spring.io/spring-ai/reference/api/chat/google-genai-chat.html" target="_blank" rel="noreferrer"><code>spring-ai-google-genai</code></a> ，实现 <a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Google Gemini</a> 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>gemini-3.1-pro-preview、gemini-3.5-flash 等</td><td>GoogleGenAiChatModel</td></tr><tr><td>AI 绘画</td><td><a href="https://ai.google.dev/gemini-api/docs/imagen?hl=zh-cn" target="_blank" rel="noreferrer">imagen-4.0-generate-001</a> 等</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>由于 Google Gemini 是非开源的模型，所以无法私有化部署，需要去官网申请 API Key，然后通过 Spring AI 提供的客户端接入。</p><p>不过，目前市面上有很多 Gemini 的中转 API 服务，通过购买这些服务，也能实现接入。</p><p>疑问：什么是“中转 API 服务”？</p><p>简单来说，就是有人通过一定的渠道，获取了大量的 Gemini、MidJourney 等 API 账号，然后部署一个 API 池子（服务）。</p><p>中转人卖给你一个 API KEY 令牌，你就可以把 AI 请求发送到他的池子：池子采取一定的算法选取一个 API 账号帮你把请求发送到大模型后端，然后再把大模型返回的结果转发给你。</p><p>下面，我们来看看这两种方式怎么申请？</p><h3 id="_1-1-方式一-官方-api-申请" tabindex="-1">1.1 方式一：官方 API 申请 <a class="header-anchor" href="#_1-1-方式一-官方-api-申请" aria-label="Permalink to &quot;1.1 方式一：官方 API 申请&quot;">​</a></h3><p>① 在 <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">Google AI Studio</a> 上，点击「创建 API 密钥」，创建一个 API Key 密钥。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为项目默认使用 Google Gemini 官方地址）。如下图所示：</p><p><img src="'+n+`" alt="官方的密钥配置"></p><p>友情提示：官方的 API 禁止国内直接访问，需要有 VPN 代理~</p><h3 id="_1-2-方式二-中转-api-申请" tabindex="-1">1.2 方式二：中转 API 申请 <a class="header-anchor" href="#_1-2-方式二-中转-api-申请" aria-label="Permalink to &quot;1.2 方式二：中转 API 申请&quot;">​</a></h3><p>提供中转 API 服务的有很多，也可以 Google 直接搜索“gemini API 中转”，例如说：</p><ul><li><a href="https://teamorouter.com/?i=24111b709f" target="_blank" rel="noreferrer">TeamoRouter</a> 【最佳推荐，官方 10% 左右的价格，Codex/Claude Code 也可以用】</li><li><a href="https://api.holdai.top/register?aff=EcRu" target="_blank" rel="noreferrer">毫秒 API</a></li><li><a href="https://aihubmix.com?aff=E13A" target="_blank" rel="noreferrer">AIHubMix</a></li></ul><hr><p>购买完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。需要填写“密钥” + “自定义 API URL”（因为让 Spring AI 使用该地址）。</p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型，并选择前面配置的 Gemini API 密钥。</p><p>如果使用官方 Gemini，模型标识可以参考下表填写；如果使用中转 API，以中转平台实际支持的模型标识为准。</p><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>gemini-3.1-pro-preview</code></td><td>65536</td></tr><tr><td><code>gemini-3.5-flash</code></td><td>65536</td></tr><tr><td><code>gemini-3.1-flash-lite-preview</code></td><td>65536</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 Imagen ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 GoogleGenAiChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>spring.ai.google.genai</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    google</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      genai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 谷歌 Gemini</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${GEMINI_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gemini-3.5-flash</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，GeminiChatModelTests 里有对应的测试用例，可以参考。</p><h2 id="_666-gemma-如何接入" tabindex="-1">666. Gemma 如何接入？ <a class="header-anchor" href="#_666-gemma-如何接入" aria-label="Permalink to &quot;666. Gemma 如何接入？&quot;">​</a></h2><p>Gemma 是 Gemini 的<a href="https://github.com/google-deepmind/gemma" target="_blank" rel="noreferrer">开源版本</a> ，可以进行私有化部署。</p><p>整个的接入，类似 <a href="./llama">《【模型接入】LLAMA》</a>。下面，我简单写下，有疑问可以星球提问哈！主要是，貌似也没听说哪个团队或者朋友在使用~</p><p>① 访问 <a href="https://ollama.ai/download" target="_blank" rel="noreferrer">Ollama 官网</a> ，下载对应系统 Ollama 客户端，然后安装。</p><p>② 安装完成后，在命令中执行 <code>ollama run gemma4</code> 命令，一键部署 <code>gemma4</code> 模型。</p><p>③ 之后，需要使用 Spring AI 的 <a href="https://github.com/spring-projects/spring-ai/tree/main/models/spring-ai-ollama" target="_blank" rel="noreferrer"><code>spring-ai-ollama</code></a> 进行接入。</p><p>不知道它怎么使用的话，可以看看 <a href="https://medium.com/@freeyecheng/spring-ai-java-integration-with-large-language-models-simplified-04873df6a538" target="_blank" rel="noreferrer">《Spring AI : Java Integration with Large Language Models Simplified》</a> 博客。</p>`,45)])])}const k=e(s,[["render",l]]);export{c as __pageData,k as default};
